var o=`0244-briam`;var i=`world-0244`;var n=`GR`;var a=`southern-europe`;var r=4;var l=75;var s={en:`Briam`,ua:`Бріам`};var d={en:`A traditional Greece dish made with potato, zucchini, eggplant, tomato. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Греція. Основні інгредієнти: картопля, цукіні, баклажан, помідор. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Wash and prepare the listed produce; dice or chop evenly for a consistent texture.`,ua:`Вимийте й підготуйте зазначені продукти; наріжте рівномірними кубиками або дрібними шматочками.`,t:[`chopping`,`dicing`],m:10,i:[[`potato`,400,`g`],[`zucchini`,400,`g`],[`eggplant`,370,`g`],[`tomato`,450,`g`],[`yellow-onion`,180,`g`]]},{en:`Roast in a preheated 190°C oven for about 65 minutes until nicely browned and fully cooked; turn once if needed.`,ua:`Запікайте в розігрітій до 190°C духовці приблизно 65 хвилин до рум’яності й готовності; за потреби переверніть.`,t:[`roasting`],m:65,i:[[`extra-virgin-olive-oil`,110,`ml`],[`garlic`,4,`clove`],[`parsley`,20,`g`],[`dried-oregano`,5,`g`],[`table-salt`,null,`to_taste`]]}];var c={slug:o,id:i,country:`GR`,region:a,servings:4,minutes:75,title:s,text:d,steps:g};export{n as country,c as default,i as id,l as minutes,a as region,r as servings,o as slug,g as steps,d as text,s as title};